settings.html:
:root { --ease-out: cubic-bezier(0.23, 1, 0.32, 1); --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1); }
.hero-enter > * { opacity:0; transform:translateY(14px); animation: heroRise 550ms var(--ease-out) forwards; }
.hero-enter > :nth-child(1) { animation-delay:20ms; } .hero-enter > :nth-child(2) { animation-delay:90ms; }
.hero-enter > :nth-child(3) { animation-delay:160ms; } .hero-enter > :nth-child(4) { animation-delay:230ms; }
.hero-enter > :nth-child(5) { animation-delay:300ms; } .hero-enter > :nth-child(6) { animation-delay:370ms; }
@keyframes heroRise { to { opacity:1; transform:translateY(0); } }
.hero-enter .hero-img img { transform:scale(1.06); animation: heroSettle 1100ms var(--ease-out) 150ms forwards; }
@keyframes heroSettle { to { transform:scale(1); } }
.reveal { opacity:0; transform:translateY(18px); transition: opacity 500ms var(--ease-out), transform 500ms var(--ease-out); }
.reveal.is-visible { opacity:1; transform:translateY(0); }
.reveal-group > * { opacity:0; transform:translateY(18px); transition: opacity 450ms var(--ease-out), transform 450ms var(--ease-out); }
.reveal-group.is-visible > * { opacity:1; transform:translateY(0); }
.reveal-group.is-visible > :nth-child(1) { transition-delay:0ms; } .reveal-group.is-visible > :nth-child(2) { transition-delay:60ms; }
.reveal-group.is-visible > :nth-child(3) { transition-delay:120ms; } .reveal-group.is-visible > :nth-child(4) { transition-delay:180ms; }
.reveal-group.is-visible > :nth-child(5) { transition-delay:240ms; } .reveal-group.is-visible > :nth-child(6) { transition-delay:300ms; }
a[class*="rounded-full"], .tab-btn { transition: transform 160ms var(--ease-out), background-color 180ms ease, color 180ms ease, border-color 180ms ease; }
a[class*="rounded-full"]:active, .tab-btn:active { transform:scale(0.97); }
#produk picture img, #testimoni picture img { transition: transform 250ms ease; }
@media (hover: hover) and (pointer: fine) { .tab-btn:hover { transform:translateY(-1px); } #produk article:hover picture img, #testimoni figure:hover picture img { transform:scale(1.05); } }
header[role="banner"] { transition: box-shadow 200ms ease; } header[role="banner"].is-scrolled { box-shadow: 0 12px 32px -8px rgba(8,42,35,0.5); }
#sticky-bar { animation: barUp 450ms var(--ease-out) 300ms both; }
@keyframes barUp { from { opacity:0; transform:translateY(100%); } to { opacity:1; transform:translateY(0); } }
.tab-panel.panel-in { animation: panelIn 220ms var(--ease-out); }
@keyframes panelIn { from { opacity:0; transform:translateY(6px); } to { opacity:1; transform:translateY(0); } }
@media (prefers-reduced-motion: reduce) { .hero-enter > *, .hero-enter .hero-img img, .reveal, .reveal.is-visible, .reveal-group > *, .reveal-group.is-visible > * { opacity:1 !important; transform:none !important; animation:none !important; } }
